 ---- update tb_client_eligibility set start_dt = v_start_dt, end_dt = v_end_dt ,eligibility_status_cd = (searchobj ->>'eligibility_status_cd') :: character varying                                              
 ---- where client_id=v_client_id and eligibility_type_cd = (searchobj ->>'eligibility_type_cd') :: character varying;                                                                                            
 ----                                                                                                                                                                                                             
