 --INSERT INTO public.tb_ssi_eligibility_events                                                                                                                                                                   
 --( start_dt, end_dt, event_type_cd, status_cd, notes_tx, status_change_sw, eligibility_id, create_ts, create_user_id, update_ts, update_user_id, delete_sw)                                                     
 --VALUES(v_event_start_dt,v_event_end_dt, (searchobj ->>'event_type_cd'):: character varying, (searchobj ->>'status_cd'):: character varying,                                                                    
 --(searchobj ->>'notes_tx') :: character varying , (searchobj ->>'status_change_sw'):: bpchar, v_eligibility_id :: integer, now(), v_securityid, now(), v_securityid, 'N');                                      
 --                                                                                                                                                                                                               
 --end if;                                                                                                                                                                                                        
                                                                                                                                                                                                                  
 return 'Success';                                                                                                                                                                                                
 END;                                                                                                                                                                                                             
                                                                                                                                                                                                                  
 $function$                                                                                                                                                                                                         

